text:
Use `pg` pool. Key config:

```js
import { Pool } from 'pg';

const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Pool sizing
  max: 20,                // max connections (default 10)
  min: 2,                 // keep alive floor
  idleTimeoutMillis: 30_000,    // kill idle conn after 30s
  connectionTimeoutMillis: 2_000, // fail fast if no conn in 2s

  // Query timeout (per-connection default)
  statement_timeout: 10_000,    // kill query after 10s
  query_timeout: 10_000,
});

// Error on idle client (prevent silent crashes)
pool.on('error', (err, client) => {
  console.error('Idle client error:', err.message);
});
```

**Query wrapper** — always release:

```js
async function query(text, params) {
  const client = await pool.connect();
  try {
    const res = await client.query(text, params);
    return res;
  } catch (err) {
    throw err;           // let caller handle
  } finally {
    client.release();    // ALWAYS runs
  }
}
```

**Transaction wrapper:**

```js
async function withTransaction(fn) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

// Usage
await withTransaction(async (client) => {
  await client.query('INSERT INTO orders ...', [...]);
  await client.query('UPDATE inventory ...', [...]);
});
```

**Graceful shutdown:**

```js
process.on('SIGTERM', async () => {
  await pool.end();      // wait for active queries, then close
  process.exit(0);
});
```

---

**Key tradeoffs:**

| Setting | Too low | Too high |
|---|---|---|
| `max` | Queue piles up | DB overwhelmed |
| `idleTimeoutMillis` | Conn churn | Stale conn accumulate |
| `connectionTimeoutMillis` | Caller waits long | Fast-fail hides real problem |

`max` rule of thumb: match Postgres `max_connections` ÷ app instances, minus 10 for admin headroom.
